# Paths to different tokenizers and maximum sequence length for the model input
TOKENIZER_PATH_DEFAULT = "notebooks/tokenizer.pkl"
TOKENIZER_PATH_ITER = "notebooks/tokenizer_iterative.pkl"
MAXLEN = 200

